}

/* ── structure builder ─────────────────────────────────────────────────── */
const structures = [];
function makeStructure(spec, panelKey, parent) {
  const g = new THREE.Group();
  g.position.x = spec.x;
  parent.add(g);

  SOLID_EDGES.forEach(([a, b]) => g.add(cyl(V[a], V[b], 0.022, GREEN)));
  g.add(dashedSeg(V.EQL, V.EQR, 0.020, GREEN_D));

  const triGeo = new THREE.BufferGeometry();
  triGeo.setAttribute('position', new THREE.Float32BufferAttribute([
    V.EQL.x, V.EQL.y, V.EQL.z, V.EQR.x, V.EQR.y, V.EQR.z, V.EQF.x, V.EQF.y, V.EQF.z
