    tooltip: 'Equatorial plane — 3 sites, 120° apart',
    body: 'The three equatorial positions lie in this plane, separated by 120°. They are the roomiest sites, so lone pairs occupy them preferentially.'
  });

  const ORIGIN = new THREE.Vector3(0, 0, 0);
  KEYS.forEach(k => {
    const role = spec.roles[k];
    if (role === 'none') return;
    if (role === 'LP') {
      const m = cyl(ORIGIN, V[k].clone().multiplyScalar(0.70), 0.030, RED);
      registerInteractive(m, {
        title: 'Lone pair',
        tooltip: 'Lone pair (non-bonding)',
        body: 'A lone pair spreads out closer to the central Cl atom, so it repels neighbouring electron pairs more strongly than a bonding pair does.'
      });
      g.add(m);
    } else {
      const m = cyl(ORIGIN, V[k].clone().multiplyScalar(0.97), 0.020, GRAY);
      if (role === 'F') registerInteractive(m, {
        title: 'Cl–F bonding pair',
        tooltip: 'Bonding pair to F',
        body: AXIAL.includes(k) ? 'An axial bond: 90° from every equatorial position and 180° from the other axial one.'
          : 'An equatorial bond: 120° from the other equatorial positions and 90° from both axial ones.'
      });
      g.add(m);
    }
  });

  // highlight halos
  const halos = { axial: [], eq: [] };
  KEYS.forEach(k => {
    const s = new THREE.Mesh(
      new THREE.SphereGeometry(0.17, 16, 12),
      new THREE.MeshBasicMaterial({ color: HL, transparent: true, opacity: 0.55, depthWrite: false })
    );
    s.position.copy(V[k]);
    s.visible = false;
    g.add(s);
    (AXIAL.includes(k) ? halos.axial : halos.eq).push(s);
  });

  // 90° repulsion arcs
  const arcs = new THREE.Group();
  arcs.visible = false;
  g.add(arcs);
  let lpbp = 0, lplp = 0;
  const lps = KEYS.filter(k => spec.roles[k] === 'LP');
