      new THREE.Vector3(spec.x, 2.25, 0),
      { fontSize: '11px', color: '#a04b00', background: 'rgba(255,255,255,0.85)' },
      panelKey, 'rep');
  }

  const rec = { panel: panelKey, group: g, halos, arcs, lpbp, lplp, hasLP: lps.length > 0 };
  structures.push(rec);
  return rec;
}

