function eqv(deg) {
  const a = THREE.MathUtils.degToRad(deg);
  return new THREE.Vector3(R_EQ * Math.cos(a), 0, R_EQ * Math.sin(a));
}
const V = {
  AXT: new THREE.Vector3(0, Y_AX, 0),
  AXB: new THREE.Vector3(0, -Y_AX, 0),
  EQF: eqv(45),    // front vertex (toward viewer, low on screen)
  EQL: eqv(165),   // left-back
  EQR: eqv(-75)    // right-back
