const AXIAL = ['AXT', 'AXB'], EQUAT = ['EQL', 'EQR', 'EQF'];
const SOLID_EDGES = [
  ['AXT', 'EQL'], ['AXT', 'EQR'], ['AXT', 'EQF'],
  ['AXB', 'EQL'], ['AXB', 'EQR'], ['AXB', 'EQF'],
  ['EQL', 'EQF'], ['EQR', 'EQF']
];

/* screen basis at the default isometric pose (az 45°, elev 35.26°) */
const SR = new THREE.Vector3(0.70711, 0, -0.70711);            // screen right
const SU = new THREE.Vector3(-0.40825, 0.81650, -0.40825);     // screen up
