    g.add(s);
    (AXIAL.includes(k) ? halos.axial : halos.eq).push(s);
  });

  // 90° repulsion arcs
  const arcs = new THREE.Group();
  arcs.visible = false;
  g.add(arcs);
  let lpbp = 0, lplp = 0;
  const lps = KEYS.filter(k => spec.roles[k] === 'LP');
  const bps = KEYS.filter(k => spec.roles[k] === 'F');
  lps.forEach(l => bps.forEach(b => {
    if (perp(l, b)) { lpbp++; arcs.add(arcTube(V[l], V[b], 0.80, ORANGE)); }
  }));
  for (let i = 0; i < lps.length; i++) for (let j = i + 1; j < lps.length; j++) {
    if (perp(lps[i], lps[j])) { lplp++; arcs.add(arcTube(V[lps[i]], V[lps[j]], 0.60, RED)); }
  }

  // labels
  if (spec.cl) mkLabel('Cl', new THREE.Vector3(spec.x, 0, 0), { fontSize: '15px', offset: [-15, 4] }, panelKey);
  if (spec.f) {
    const off = { AXT: [0, -13], AXB: [0, 14], EQL: [-13, -2], EQR: [13, -2], EQF: [14, 9] };
    KEYS.filter(k => spec.roles[k] === 'F').forEach(k => {
      const p = V[k].clone().multiplyScalar(1.20); p.x += spec.x;
      mkLabel('F', p, { fontSize: '15px', offset: off[k] }, panelKey);
    });
  }
  if (lps.length) {
    mkLabel(
      `90° contacts: ${lpbp} LP–BP` + (lplp ? ` + ${lplp} LP–LP` : ''),
      Sat(spec.x, 0, BADGE_Y),
      { fontSize: '11px', color: '#a04b00', background: 'rgba(255,255,255,0.9)' },
      panelKey, 'rep');
  }

  // extent points for framing (vertices padded outward to leave room for labels)
  KEYS.forEach(k => pts.push(V[k].clone().multiplyScalar(1.30).add(new THREE.Vector3(spec.x, 0, 0))));

  const rec = { panel: panelKey, group: g, halos, arcs, lpbp, lplp, hasLP: lps.length > 0 };
  structures.push(rec);
  return rec;
}

/* ── panel definitions ─────────────────────────────────────────────────── */
const PANELS = {
  a: {
    caption: '(a)', sepS: SEP_A,
    structures: [{ x: 0, roles: { AXT: 'empty', AXB: 'empty', EQL: 'empty', EQR: 'empty', EQF: 'empty' }, cl: false, f: false }]
  },
  b: {
    caption: '(b)', sepS: SEP_BCD,
    structures: [
      { x: -2.1, roles: { AXT: 'F', AXB: 'F', EQL: 'F', EQR: 'LP', EQF: 'LP' }, cl: true, f: false },
      { x: 2.1, roles: { AXT: 'F', AXB: 'F', EQL: 'F', EQR: 'none', EQF: 'none' }, cl: true, f: true }
    ]
  },
  c: {
    caption: '(c)', sepS: SEP_BCD,
    structures: [
      { x: -2.1, roles: { AXT: 'LP', AXB: 'LP', EQL: 'F', EQR: 'F', EQF: 'F' }, cl: true, f: false },
      { x: 2.1, roles: { AXT: 'none', AXB: 'none', EQL: 'F', EQR: 'F', EQF: 'F' }, cl: true, f: true }
    ]
  },
  d: {
    caption: '(d)', sepS: SEP_BCD,
    structures: [
      { x: -2.1, roles: { AXT: 'LP', AXB: 'F', EQL: 'F', EQR: 'LP', EQF: 'F' }, cl: true, f: false },
      { x: 2.1, roles: { AXT: 'none', AXB: 'F', EQL: 'F', EQR: 'none', EQF: 'F' }, cl: true, f: true }
    ]
  }
};

const panelRoots = {}, panelPts = {};
Object.keys(PANELS).forEach(key => {
  const P = PANELS[key];
  const root = new THREE.Group();
  panelRoots[key] = root;
  const pts = []; panelPts[key] = pts;
  P.structures.forEach(s => makeStructure(s, key, root, pts));
  // dashed panel separators, built along the screen-vertical basis
  [-P.sepS, P.sepS].forEach(sx => {
    root.add(dashedSeg(S(sx, -SEP_H), S(sx, SEP_H), 0.013, BLACK, 0.2, 0.18));
    pts.push(S(sx, -SEP_H), S(sx, SEP_H));
  });
  mkLabel(P.caption, S(0, CAP_Y), { fontSize: '15px' }, key);
  pts.push(S(0, CAP_Y - 0.18));
});

/* ── panel (a) elbowed leader lines ────────────────────────────────────── */
{
  const root = panelRoots.a, pts = panelPts.a;

  // Equatorial: vertical line at screen-x −1.90, elbow, then horizontally into EQL
  const eqSy = SU.dot(V.EQL);
  const elbow = S(-1.90, eqSy);
  const eqTop = S(-1.90, 1.85);
  const eqLineH = cyl(V.EQL, elbow, 0.016, BLACK);
  const eqLineV = cyl(elbow, eqTop, 0.016, BLACK);
  root.add(eqLineH); root.add(eqLineV);
  [eqLineH, eqLineV].forEach(o => registerInteractive(o, {
    title: 'Equatorial positions',
    tooltip: 'Equatorial positions (3)',
    body: 'Three equatorial sites lie in the shaded plane, 120° from each other and 90° from both axial sites — the roomiest positions.'
  }));
  pts.push(eqTop, S(-2.35, 1.95));

  // Axial: short horizontal line entering the top axial vertex from the right
  const axSy = SU.dot(V.AXT);
  const axEnd = S(0.95, axSy);
  const axLine = cyl(V.AXT, axEnd, 0.016, BLACK);
  root.add(axLine);
  registerInteractive(axLine, {
    title: 'Axial positions',
    tooltip: 'Axial positions (2)',
    body: 'Two axial sites sit on the vertical axis, 180° from each other and only 90° from all three equatorial sites.'
  });
  pts.push(S(1.60, axSy));

  const eqLab = mkLabel('Equatorial', eqTop, { fontSize: '14px', offset: [0, -12] }, 'a');
  const axLab = mkLabel('Axial', axEnd, { fontSize: '14px', offset: [26, 0] }, 'a');
  [[eqLab, 'equatorial'], [axLab, 'axial']].forEach(([lab, mode]) => {
    lab.div.style.pointerEvents = 'auto';
    lab.div.style.cursor = 'pointer';
    lab.div.style.textDecoration = 'underline dotted';
    lab.div.title = 'Click to highlight this set of positions';
    lab.div.addEventListener('click', () => setHighlight(highlight === mode ? 'none' : mode));
  });
}

/* ── per-panel framing (tight, from real content points) ───────────────── */
function fitPanel(resetPose) {
  const pts = panelPts[curPanel];
  const center = new THREE.Vector3();
  pts.forEach(p => center.add(p));
  center.multiplyScalar(1 / pts.length);

  let dir;
  if (resetPose) {
    const az = THREE.MathUtils.degToRad(45), el = THREE.MathUtils.degToRad(35.264389682754654);
    dir = new THREE.Vector3(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el));
  } else {
    dir = camera.position.clone().sub(controls.target);
    if (dir.lengthSq() < 1e-9) dir.set(1, 1, 1);
    dir.normalize();
  }

  const radius = 18;
  camera.up.set(0, 1, 0);
  camera.position.copy(center).addScaledVector(dir, radius);
  controls.target.copy(center);
  camera.lookAt(center);
  camera.near = 0.01;
  camera.far = radius * 4 + 100;
  camera.updateMatrixWorld();

  const toView = camera.matrixWorldInverse;
  const p = new THREE.Vector3();
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  pts.forEach(q => {
    p.copy(q).applyMatrix4(toView);
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
    minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
  });
  const frac = 0.90;
  const zH = (2 * d * frac) / Math.max(maxY - minY, 1e-6);
  const zW = (2 * d * aspect * frac) / Math.max(maxX - minX, 1e-6);
  camera.zoom = Math.max(0.2, Math.min(zH, zW, 5));
  camera.updateProjectionMatrix();
  controls.update();

  HOME_POS.copy(camera.position);
  HOME_TARGET.copy(controls.target);
  HOME_ZOOM = camera.zoom;
  _labelZoomRef = camera.zoom;   // keep label size constant across panels
  _lastViewArgs = null;          // our own fit is authoritative from now on
}

/* ── state + UI ────────────────────────────────────────────────────────── */
let curPanel = 'a', showRep = false, highlight = 'none', fittedPanel = null;

function refresh() {
  Object.keys(panelRoots).forEach(k => {
    const root = panelRoots[k];
    if (k === curPanel) { if (!root.parent) scene.add(root); }
    else if (root.parent) scene.remove(root);
  });
  structures.forEach(s => {
    s.arcs.visible = showRep && s.panel === curPanel && s.hasLP;
    s.halos.axial.forEach(h => h.visible = (s.panel === curPanel && highlight === 'axial'));
    s.halos.eq.forEach(h => h.visible = (s.panel === curPanel && highlight === 'equatorial'));
  });
  allLabels.forEach(L => {
    let vis = (L.panel === curPanel);
    if (L.kind === 'rep') vis = vis && showRep;
    L.entry.div.style.visibility = vis ? 'visible' : 'hidden';
  });

  const rec = structures.find(s => s.panel === curPanel && s.hasLP);
  const out = document.getElementById('repCount');
  out.textContent = (showRep && rec)
    ? `Panel (${curPanel}): ${rec.lpbp} lone-pair–bond-pair at 90°` +
      (rec.lplp ? ` + ${rec.lplp} lone-pair–lone-pair at 90°` : '')
    : '';

  document.querySelectorAll('.panelBtn').forEach(b => b.classList.toggle('active', b.dataset.p === curPanel));
  document.getElementById('hlAx').classList.toggle('active', highlight === 'axial');
  document.getElementById('hlEq').classList.toggle('active', highlight === 'equatorial');
  document.getElementById('hlNone').classList.toggle('active', highlight === 'none');
  document.getElementById('chkRep').checked = showRep;

  if (fittedPanel !== curPanel) { fittedPanel = curPanel; fitPanel(false); }
}
function setPanel(p) { curPanel = p; refresh(); }
function setHighlight(m) { highlight = m; refresh(); }

document.querySelectorAll('.panelBtn').forEach(b =>
  b.addEventListener('click', () => setPanel(b.dataset.p)));
document.getElementById('chkRep').addEventListener('change', e => { showRep = e.target.checked; refresh(); });
document.getElementById('hlAx').addEventListener('click', () => setHighlight('axial'));
document.getElementById('hlEq').addEventListener('click', () => setHighlight('equatorial'));
document.getElementById('hlNone').addEventListener('click', () => setHighlight('none'));

/* ── guided tour ───────────────────────────────────────────────────────── */
const STEPS = [
  {
    t: 'Two kinds of positions', p: 'a', r: false, h: 'none',
    n: 'The trigonal bipyramid offers two axial sites on the vertical axis and three equatorial sites in the shaded horizontal plane. Orbit the frame: equatorial neighbours sit 120° apart, axial-to-equatorial angles are only 90°.'
  },
  {
    t: '(b) Both lone pairs equatorial', p: 'b', r: true, h: 'none',
    n: 'Placing both lone pairs (red) in the roomy equatorial plane leaves F atoms at the two axial sites and one equatorial site — only 4 lone-pair–bond-pair contacts at 90°. This is the T-shaped structure actually observed for ClF₃.'
  },
  {
    t: '(c) Both lone pairs axial', p: 'c', r: true, h: 'none',
    n: 'Forcing both lone pairs onto the axis puts each of them 90° from all three bonding pairs — six close lone-pair–bond-pair contacts, the most repulsive option.'
  },
  {
    t: '(d) One axial, one equatorial', p: 'd', r: true, h: 'none',
    n: 'A mixed arrangement gives 3 lone-pair–bond-pair contacts at 90°, but also puts the two lone pairs themselves only 90° apart — worse than (b), where they are 120° apart.'
  },
  {
    t: 'Why T-shaped wins', p: 'b', r: false, h: 'equatorial',
    n: 'Back to (b), with the equatorial set highlighted: lone pairs always seek the equatorial sites, where 120° separation minimises repulsion. That uniquely fixes the T-shaped geometry of ClF₃.'
  }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  curPanel = s.p; showRep = s.r; highlight = s.h;
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}/${STEPS.length} · ${s.t}`;
  document.getElementById('stepText').textContent = s.n;
  refresh();
}
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── camera ────────────────────────────────────────────────────────────── */
goToStep(0);                                   // puts panel (a) into the scene
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.6 });
fitPanel(true);                                // tighter, content-point based framing
controls.minPolarAngle = 0.25;
controls.maxPolarAngle = Math.PI - 0.25;
const _btnReset = document.getElementById('btnReset');
_btnReset.style.display = '';
_btnReset.addEventListener('click', () => fitPanel(true));
window.addEventListener('resize', () => { setTimeout(() => fitPanel(false), 0); });
// @FIGURE_CODE_END

