// bipyramid edge (8 solid)   → CylinderGeometry r=0.026, olive #8CC63F
// rear equatorial edge       → dashed chain of short cylinders, #7FAF37
// equatorial plane           → triangle BufferGeometry, MeshBasicMaterial #DCE9B8 op .45,
//                              depthWrite:false, polygonOffset (pushed back so the
//                              coplanar gray sticks stay crisp), DoubleSide
// bonding / empty stick      → CylinderGeometry r=0.024, gray #9A9A9A, 0.97·R
// lone-pair stick            → CylinderGeometry r=0.036, dark red #A0342A, 0.70·R
// highlight halo             → SphereGeometry(0.18), #F5A623, opacity .5
// 90° repulsion arc          → TubeGeometry along a great circle, r=0.016, #E08214 (LP–LP dark red)
// panel separators           → dashed cylinder chain, black, along the SCREEN-up basis
// panel (a) leader lines     → CylinderGeometry r=0.018, black, elbowed
// all text (Cl, F, Axial, Equatorial, captions, badges) → addLabel HTML
// ────────────────────────────────────────────────────────────────────────────

const GREEN = 0x8CC63F, GREEN_D = 0x7FAF37, FILL = 0xDCE9B8;
const GRAY = 0x9A9A9A, RED = 0xA0342A, BLACK = 0x111111, HL = 0xF5A623, ORANGE = 0xE08214;

/* ── home pose: az 45°, elev 20° (low tilt → symmetric apexes, as in source) ─ */
const AZ_DEG = 45, EL_DEG = 20;
const _az = THREE.MathUtils.degToRad(AZ_DEG), _el = THREE.MathUtils.degToRad(EL_DEG);
const VIEWDIR = new THREE.Vector3(Math.cos(_az) * Math.cos(_el), Math.sin(_el), Math.sin(_az) * Math.cos(_el));
const SR = new THREE.Vector3(Math.sin(_az), 0, -Math.cos(_az));           // screen right
const SU = new THREE.Vector3().crossVectors(VIEWDIR, SR).normalize();      // screen up
const S = (sx, sy) => SR.clone().multiplyScalar(sx).add(SU.clone().multiplyScalar(sy));
// axisScreenAngles that invert to (az=45°, elev=20°): tan φ = sin(elev)·cot(45°)
const PHI = THREE.MathUtils.radToDeg(Math.atan(Math.sin(_el)));

/* ── one trigonal bipyramid, rotated 20° off the view azimuth so the front
      equatorial vertex never collapses onto the vertical axis ─────────────── */
const R_EQ = 1.35, Y_AX = 1.7;
function eqv(deg) {
  const a = THREE.MathUtils.degToRad(deg);
  return new THREE.Vector3(R_EQ * Math.cos(a), 0, R_EQ * Math.sin(a));
}
const V = {
  AXT: new THREE.Vector3(0, Y_AX, 0),
  AXB: new THREE.Vector3(0, -Y_AX, 0),
  EQF: eqv(25),    // front  (nearest viewer, projects low-right of centre)
  EQL: eqv(145),   // left-back
  EQR: eqv(265)    // right-back
};
const KEYS = ['AXT', 'AXB', 'EQL', 'EQR', 'EQF'];
const AXIAL = ['AXT', 'AXB'], EQUAT = ['EQL', 'EQR', 'EQF'];
const SOLID_EDGES = [
  ['AXT', 'EQL'], ['AXT', 'EQR'], ['AXT', 'EQF'],
  ['AXB', 'EQL'], ['AXB', 'EQR'], ['AXB', 'EQF'],
  ['EQL', 'EQF'], ['EQR', 'EQF']
];

/* ── primitive helpers ─────────────────────────────────────────────────── */
function cyl(a, b, r, color, opts = {}) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(
    new THREE.CylinderGeometry(r, r, len, 10, 1, false),
    new THREE.MeshBasicMaterial(Object.assign({ color }, opts))
  );
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
function dashedSeg(a, b, r, color, dash = 0.17, gap = 0.13) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const u = dir.clone().normalize();
  let t = 0;
  while (t < len - 1e-4) {
    const t2 = Math.min(t + dash, len);
    g.add(cyl(a.clone().addScaledVector(u, t), a.clone().addScaledVector(u, t2), r, color));
    t = t2 + gap;
  }
  return g;
}
function arcTube(a, b, radius, color) {
  const u = a.clone().normalize(), w = b.clone().normalize();
  const ang = u.angleTo(w);
  const axis = new THREE.Vector3().crossVectors(u, w).normalize();
  const pts = [];
  for (let i = 0; i <= 24; i++) pts.push(u.clone().applyAxisAngle(axis, ang * (i / 24)).multiplyScalar(radius));
  return new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 40, 0.016, 6, false),
    new THREE.MeshBasicMaterial({ color })
  );
}
const perp = (k1, k2) => Math.abs(V[k1].clone().normalize().dot(V[k2].clone().normalize())) < 1e-6;

/* ── label bookkeeping ─────────────────────────────────────────────────── */
const allLabels = [];
function mkLabel(text, pos, opts, panel, kind) {
  const e = addLabel(text, pos, opts);
  allLabels.push({ entry: e, panel, kind: kind || 'base' });
  return e;
}

/* ── screen-space layout constants ─────────────────────────────────────── */
const CAP_Y = -2.90;    // caption row
const BADGE_Y = 2.20;   // 90°-contact badge
const SEP_H = 2.85;     // separator half height
const PANEL_X = { a: -10.5, b: -3.4, c: 4.6, d: 12.4 };   // panel centres, screen-x
const SEP_X = [-7.6, 0.6, 8.5];                            // separators BETWEEN panels only

/* ── structure builder ─────────────────────────────────────────────────── */
const structures = [];
function makeStructure(spec, panelKey, root, rootPos, pts) {
  const g = new THREE.Group();
  const off = SR.clone().multiplyScalar(spec.sx);
  g.position.copy(off);
  root.add(g);
  const base = rootPos.clone().add(off);

  // green frame
  SOLID_EDGES.forEach(([a, b]) => g.add(cyl(V[a], V[b], 0.026, GREEN)));
  g.add(dashedSeg(V.EQL, V.EQR, 0.022, GREEN_D));

  // shaded equatorial plane (pushed back in depth so coplanar sticks stay crisp)
  const triGeo = new THREE.BufferGeometry();
  triGeo.setAttribute('position', new THREE.Float32BufferAttribute([
    V.EQL.x, V.EQL.y, V.EQL.z, V.EQR.x, V.EQR.y, V.EQR.z, V.EQF.x, V.EQF.y, V.EQF.z
  ], 3));
  triGeo.computeVertexNormals();
  const tri = new THREE.Mesh(triGeo, new THREE.MeshBasicMaterial({
    color: FILL, transparent: true, opacity: 0.45, depthWrite: false, side: THREE.DoubleSide,
    polygonOffset: true, polygonOffsetFactor: 2, polygonOffsetUnits: 2
  }));
  g.add(tri);
  registerInteractive(tri, {
    title: 'Equatorial plane',
    tooltip: 'Equatorial plane — 3 sites, 120° apart',
    body: 'The three equatorial positions lie in this plane, separated by 120°. They are the roomiest sites, so lone pairs occupy them preferentially.'
  });

  // internal sticks
  const ORIGIN = new THREE.Vector3(0, 0, 0);
  KEYS.forEach(k => {
    const role = spec.roles[k];
    if (role === 'none') return;
    if (role === 'LP') {
      const m = cyl(ORIGIN, V[k].clone().multiplyScalar(0.70), 0.036, RED);
      m.renderOrder = 2;
      registerInteractive(m, {
        title: 'Lone pair',
        tooltip: 'Lone pair (non-bonding)',
        body: 'A lone pair stays closer to the central Cl atom and spreads out more, so it repels neighbouring electron pairs more strongly than a bonding pair does.'
      });
      g.add(m);
    } else {
      const m = cyl(ORIGIN, V[k].clone().multiplyScalar(0.97), 0.024, GRAY);
      m.renderOrder = 2;
      if (role === 'F') registerInteractive(m, {
        title: 'Cl–F bonding pair',
        tooltip: 'Bonding pair to F',
        body: AXIAL.includes(k)
          ? 'An axial bond: 90° from every equatorial position and 180° from the other axial one.'
          : 'An equatorial bond: 120° from the other equatorial positions and 90° from both axial ones.'
      });
      g.add(m);
    }
  });

  // highlight halos
  const halos = { axial: [], eq: [] };
  KEYS.forEach(k => {
    const s = new THREE.Mesh(
      new THREE.SphereGeometry(0.18, 16, 12),
      new THREE.MeshBasicMaterial({ color: HL, transparent: true, opacity: 0.5, depthWrite: false })
    );
    s.position.copy(V[k]);
    s.visible = false;
    g.add(s);
    (AXIAL.includes(k) ? halos.axial : halos.eq).push(s);
  });

  // 90° repulsion arcs
  const arcs = new THREE.Group();
  arcs.visible = false;
  g.add(arcs);
  let lpbp = 0, lplp = 0;
  const lps = KEYS.filter(k => spec.roles[k] === 'LP');
  const bps = KEYS.filter(k => spec.roles[k] === 'F');
  lps.forEach(l => bps.forEach(b => {
    if (perp(l, b)) { lpbp++; arcs.add(arcTube(V[l], V[b], 0.82, ORANGE)); }
  }));
  for (let i = 0; i < lps.length; i++) for (let j = i + 1; j < lps.length; j++) {
    if (perp(lps[i], lps[j])) { lplp++; arcs.add(arcTube(V[lps[i]], V[lps[j]], 0.60, RED)); }
  }

  // labels
  if (spec.cl) mkLabel('Cl', base.clone(), { fontSize: '15px', offset: [-13, 3] }, panelKey);
  if (spec.f) {
    const off2 = { AXT: [0, -13], AXB: [0, 14], EQL: [-15, -2], EQR: [15, -7], EQF: [13, 11] };
    KEYS.filter(k => spec.roles[k] === 'F').forEach(k => {
      mkLabel('F', base.clone().add(V[k].clone().multiplyScalar(1.16)),
        { fontSize: '15px', offset: off2[k] }, panelKey);
    });
  }
  if (lps.length) {
    mkLabel(
      `90°: ${lpbp} LP–BP` + (lplp ? ` + ${lplp} LP–LP` : ''),
      base.clone().add(S(0, BADGE_Y)),
      { fontSize: '11px', color: '#a04b00', background: 'rgba(255,255,255,0.92)' },
      panelKey, 'rep');
  }

  KEYS.forEach(k => pts.push(base.clone().add(V[k].clone().multiplyScalar(1.30))));
  pts.push(base.clone().add(S(0, BADGE_Y + 0.15)));

  const rec = { panel: panelKey, group: g, halos, arcs, lpbp, lplp, hasLP: lps.length > 0 };
  structures.push(rec);
  return rec;
}

/* ── panel definitions (arrangements straight from the source) ─────────── */
const PANELS = {
  a: {
    caption: '(a)',
    structures: [{ sx: 0, roles: { AXT: 'empty', AXB: 'empty', EQL: 'empty', EQR: 'empty', EQF: 'empty' }, cl: false, f: false }]
  },
  b: {
    caption: '(b)',
    structures: [
      { sx: -2.1, roles: { AXT: 'F', AXB: 'F', EQL: 'F', EQR: 'LP', EQF: 'LP' }, cl: true, f: false },
      { sx: 2.1, roles: { AXT: 'F', AXB: 'F', EQL: 'F', EQR: 'none', EQF: 'none' }, cl: true, f: true }
    ]
  },
  c: {
    caption: '(c)',
    structures: [
      { sx: -2.1, roles: { AXT: 'LP', AXB: 'LP', EQL: 'F', EQR: 'F', EQF: 'F' }, cl: true, f: false },
      { sx: 2.1, roles: { AXT: 'none', AXB: 'none', EQL: 'F', EQR: 'F', EQF: 'F' }, cl: true, f: true }
    ]
  },
  d: {
    caption: '(d)',
    structures: [
      { sx: -2.1, roles: { AXT: 'LP', AXB: 'F', EQL: 'F', EQR: 'LP', EQF: 'F' }, cl: true, f: false },
      { sx: 2.1, roles: { AXT: 'none', AXB: 'F', EQL: 'F', EQR: 'none', EQF: 'F' }, cl: true, f: true }
    ]
  }
};

const panelRoots = {}, panelPts = {};
Object.keys(PANELS).forEach(key => {
  const P = PANELS[key];
  const root = new THREE.Group();
  const rootPos = SR.clone().multiplyScalar(PANEL_X[key]);
  root.position.copy(rootPos);
  panelRoots[key] = root;
  const pts = []; panelPts[key] = pts;
  P.structures.forEach(s => makeStructure(s, key, root, rootPos, pts));
  mkLabel(P.caption, rootPos.clone().add(S(0, CAP_Y)), { fontSize: '15px' }, key);
  pts.push(rootPos.clone().add(S(0, CAP_Y - 0.2)));
});

/* ── dashed separators BETWEEN panels (only shown in the all-panel view) ─ */
const sepGroup = new THREE.Group();
const sepPts = [];
SEP_X.forEach(sx => {
  sepGroup.add(dashedSeg(S(sx, -SEP_H), S(sx, SEP_H), 0.014, BLACK, 0.20, 0.18));
  sepPts.push(S(sx, -SEP_H), S(sx, SEP_H));
});

/* ── panel (a) elbowed leader lines ────────────────────────────────────── */
{
  const root = panelRoots.a, pts = panelPts.a;
  const rootPos = root.position.clone();

  const eqSy = SU.dot(V.EQL);
  const elbow = S(-2.40, eqSy);
  const eqTop = S(-2.40, 2.35);
  const eqLineH = cyl(V.EQL, elbow, 0.018, BLACK);
  const eqLineV = cyl(elbow, eqTop, 0.018, BLACK);
  root.add(eqLineH); root.add(eqLineV);
  [eqLineH, eqLineV].forEach(o => registerInteractive(o, {
    title: 'Equatorial positions',
    tooltip: 'Equatorial positions (3)',
    body: 'Three equatorial sites lie in the shaded plane, 120° from each other and 90° from both axial sites — the roomiest positions.'
  }));

  const axSy = SU.dot(V.AXT);
  const axEnd = S(1.35, axSy);
  const axLine = cyl(V.AXT, axEnd, 0.018, BLACK);
  root.add(axLine);
  registerInteractive(axLine, {
    title: 'Axial positions',
    tooltip: 'Axial positions (2)',
    body: 'Two axial sites sit on the vertical axis, 180° from each other and only 90° from all three equatorial sites.'
  });

  pts.push(rootPos.clone().add(eqTop), rootPos.clone().add(S(-3.0, 2.55)),
    rootPos.clone().add(S(2.35, axSy)));

  const eqLab = mkLabel('Equatorial', rootPos.clone().add(eqTop), { fontSize: '14px', offset: [0, -12] }, 'a');
  const axLab = mkLabel('Axial', rootPos.clone().add(axEnd), { fontSize: '14px', offset: [24, 0] }, 'a');
  [[eqLab, 'equatorial'], [axLab, 'axial']].forEach(([lab, mode]) => {
    lab.div.style.pointerEvents = 'auto';
    lab.div.style.cursor = 'pointer';
    lab.div.style.textDecoration = 'underline dotted';
