}

/* ── views ─────────────────────────────────────────────────────────────── */
const VIEWS = {
  all: { panels: ['a', 'b', 'c', 'd'], sep: true, labelScale: 0.68 },
  a: { panels: ['a'], sep: false, labelScale: 1 },
  b: { panels: ['b'], sep: false, labelScale: 1 },
  c: { panels: ['c'], sep: false, labelScale: 1 },
  d: { panels: ['d'], sep: false, labelScale: 1 }
};

function fitView(reset) {
  const view = VIEWS[curView];
  const pts = [];
  view.panels.forEach(k => panelPts[k].forEach(p => pts.push(p)));
  if (view.sep) sepPts.forEach(p => pts.push(p));
  const box = new THREE.Box3().setFromPoints(pts);
  const center = box.getCenter(new THREE.Vector3());

  let dir;
  if (reset) dir = VIEWDIR.clone();
  else {
    dir = camera.position.clone().sub(controls.target);
    if (dir.lengthSq() < 1e-9) dir.copy(VIEWDIR);
    dir.normalize();
  }

  const radius = 45;
  camera.up.set(0, 1, 0);
  camera.position.copy(center).addScaledVector(dir, radius);
  controls.target.copy(center);
  camera.lookAt(center);
  camera.near = 0.01;
  camera.far = radius * 4 + 200;
  camera.updateMatrixWorld();

  const m = camera.matrixWorldInverse, p = new THREE.Vector3();
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  pts.forEach(q => {
    p.copy(q).applyMatrix4(m);
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
    minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
  });
  const frac = 0.92;
  const zH = (2 * d * frac) / Math.max(maxY - minY, 1e-6);
  const zW = (2 * d * aspect * frac) / Math.max(maxX - minX, 1e-6);
  camera.zoom = Math.max(0.12, Math.min(zH, zW, 5));
  camera.updateProjectionMatrix();
  controls.update();

  HOME_POS.copy(camera.position);
  HOME_TARGET.copy(controls.target);
  HOME_ZOOM = camera.zoom;
  _labelZoomRef = camera.zoom / (view.labelScale || 1);
  _lastViewArgs = null;
}

/* ── state + UI ────────────────────────────────────────────────────────── */
let curView = 'all', showRep = false, highlight = 'none', fittedView = null;

function refresh() {
  const view = VIEWS[curView];
  Object.keys(panelRoots).forEach(k => {
    const root = panelRoots[k];
    const on = view.panels.includes(k);
    if (on) { if (!root.parent) scene.add(root); }
    else if (root.parent) scene.remove(root);
  });
  if (view.sep) { if (!sepGroup.parent) scene.add(sepGroup); }
  else if (sepGroup.parent) scene.remove(sepGroup);

  structures.forEach(s => {
    const on = view.panels.includes(s.panel);
    s.arcs.visible = on && showRep && s.hasLP;
    s.halos.axial.forEach(h => h.visible = on && highlight === 'axial');
    s.halos.eq.forEach(h => h.visible = on && highlight === 'equatorial');
  });
  allLabels.forEach(L => {
    let vis = view.panels.includes(L.panel);
    if (L.kind === 'rep') vis = vis && showRep;
    L.entry.div.style.visibility = vis ? 'visible' : 'hidden';
  });

  const out = document.getElementById('repCount');
  if (!showRep) out.textContent = '';
  else {
    const txt = view.panels
      .map(k => structures.find(s => s.panel === k && s.hasLP))
      .filter(Boolean)
      .map(r => `(${r.panel}) ${r.lpbp} LP–BP` + (r.lplp ? ` + ${r.lplp} LP–LP` : ''))
      .join('  ·  ');
    out.textContent = txt ? `90° contacts — ${txt}` : 'Panel (a) has no lone pairs.';
  }

  document.querySelectorAll('.viewBtn').forEach(b => b.classList.toggle('active', b.dataset.v === curView));
  document.getElementById('hlAx').classList.toggle('active', highlight === 'axial');
  document.getElementById('hlEq').classList.toggle('active', highlight === 'equatorial');
  document.getElementById('hlNone').classList.toggle('active', highlight === 'none');
  document.getElementById('chkRep').checked = showRep;

  if (fittedView !== curView) { fittedView = curView; fitView(false); }
}
function setView(v) { curView = v; refresh(); }
function setHighlight(m) { highlight = m; refresh(); }

document.querySelectorAll('.viewBtn').forEach(b =>
  b.addEventListener('click', () => setView(b.dataset.v)));
document.getElementById('chkRep').addEventListener('change', e => { showRep = e.target.checked; refresh(); });
document.getElementById('hlAx').addEventListener('click', () => setHighlight('axial'));
document.getElementById('hlEq').addEventListener('click', () => setHighlight('equatorial'));
document.getElementById('hlNone').addEventListener('click', () => setHighlight('none'));

